/**
 * IDs of orders containing a product (or one of its variations).
 *
 * @param int      $product_id Product or variation ID.
 * @param string[] $statuses   Order statuses without "wc-" (empty = any).
 * @return int[]
 */
function perfectpixel_get_order_ids_with_product( $product_id, $statuses = array() ) {
	global $wpdb;
	$ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT DISTINCT i.order_id FROM {$wpdb->prefix}woocommerce_order_items i
			INNER JOIN {$wpdb->prefix}woocommerce_order_itemmeta m ON m.order_item_id = i.order_item_id
			WHERE i.order_item_type = 'line_item' AND m.meta_key IN ('_product_id','_variation_id') AND m.meta_value = %d",
			$product_id
		)
	);
	if ( ! $ids ) {
		return array();
	}
	// Load through the CRUD so it works with either order storage (posts or HPOS).
	$statuses = array_map( 'sanitize_key', (array) $statuses );
	$result   = array();
	foreach ( $ids as $order_id ) {
		$order = wc_get_order( (int) $order_id );
		if ( $order && 'shop_order' === $order->get_type() && ( ! $statuses || $order->has_status( $statuses ) ) ) {
			$result[] = $order->get_id();
		}
	}
	return $result;
}
